{
  "about": "Conditions: states applied to a creature for a while (or until removed). modifiers use the Orsino vocabulary (see src/rules/modifiers.ts); onTurnEnd damage or healing happens at the end of the holder's turn, or on each tick of a world-time clock. Orsino statuses are generated into data/catalog/orsino/conditions.json; this file holds Kyr's own conditions and deliberate adaptations of Orsino ones.",
  "conditions": {
    "poisoned": {
      "name": "Poisoned",
      "description": "Poison works through the body, hurting a little at a time until it is cured.",
      "lifetime": "persistent",
      "modifiers": {
        "onTurnEnd": [
          {
            "kind": "damage",
            "amount": "2",
            "damageType": "poison"
          }
        ]
      },
      "saveKind": "poison",
      "source": {
        "kyr": true,
        "notes": "A world condition that lasts beyond an encounter and is cured by an antidote; Orsino's poison ends with the fight."
      }
    },
    "bleeding": {
      "name": "Bleeding",
      "description": "A wound that keeps bleeding until it is bound.",
      "lifetime": "persistent",
      "modifiers": {
        "onTurnEnd": [
          {
            "kind": "damage",
            "amount": "1",
            "damageType": "bleed"
          }
        ]
      },
      "saveKind": "bleed",
      "source": {
        "kyr": true,
        "notes": "A world condition treated by rest or a poultice; Orsino's bleed ends with the fight."
      }
    },
    "fireproof": {
      "name": "Fireproof",
      "description": "Fire does half its harm.",
      "lifetime": "persistent",
      "modifiers": {
        "resistances": {
          "fire": 0.5
        }
      },
      "stacking": "source-refresh",
      "source": {
        "orsino": "status:fireproof",
        "fidelity": "adapted",
        "notes": "Exact 50% fire resistance. It persists beyond an encounter for as long as the applying salve or ward says, and one source refreshes rather than stacks."
      }
    },
    "wayfarer_guard": {
      "name": "Wayfarer's guard",
      "description": "Veyra watches over the traveller: saves come easier.",
      "lifetime": "persistent",
      "modifiers": {
        "saveVersusAll": 2
      },
      "stacking": "source-refresh",
      "source": {
        "kyr": true
      }
    },
    "lit": {
      "name": "Lit",
      "description": "A conjured light hangs over its bearer's shoulder for a while.",
      "lifetime": "persistent",
      "modifiers": {},
      "grants": [
        "light"
      ],
      "source": {
        "kyr": true,
        "notes": "Kyr's light: while it lasts, the company can see in unlit places."
      },
      "ends": "The light over {target}'s shoulder fades.",
      "begins": "A small steady light kindles over {target}'s shoulder."
    },
    "torchlit": {
      "name": "Torchlit",
      "description": "Carrying a burning torch: light against the dark, and fire to hand.",
      "lifetime": "persistent",
      "modifiers": {},
      "grants": [
        "light",
        "flame"
      ],
      "begins": "{target} lights a torch.",
      "ends": "{target}'s torch gutters out.",
      "source": {
        "kyr": true,
        "notes": "A torch burns about an hour: light in unlit places, and a flame for what needs burning."
      }
    },
    "unbarring": {
      "name": "Unbarring",
      "description": "Locks open at a touch for a while.",
      "lifetime": "persistent",
      "modifiers": {},
      "grants": [
        "lockwork"
      ],
      "begins": "Locks will open at {target}'s touch for the next hour.",
      "ends": "The unbarring on {target}'s hands is spent.",
      "source": {
        "kyr": true,
        "notes": "The effect of Knock: for an hour its bearer opens what lockwork opens."
      }
    },
    "guarded": {
      "name": "Guarded",
      "description": "Someone stands in front of them and takes the blows meant for them.",
      "begins": "Until their guard acts again, blows aimed at {target} meet the guard instead.",
      "ends": "{target} is no longer guarded.",
      "lifetime": "encounter",
      "modifiers": {},
      "guard": true,
