data/institutions/keepers-of-names/insti:
Module keepers_of_names "The Keepers of Names" {
  Description "A burial society that holds the river settlements' dead in custody: their registers, their shrines and the guardians they set over them. It claims no treasure, only that the named dead stay named.".
  Entity party: group "Your company".
  Place shrine "Where the keepers keep their shrine" is room.

  Entity register_survives: fact "The keepers' register of the dead survives. Its family numbers name the remains below; those dead belong to the settlements that sheltered together, not to whoever reaches them first".
  Initially Assert established(register_survives).
  Entity custody_writ: fact "A keeper's custody writ, granting supervised access to the named dead".
  Initially Assert established(custody_writ).

  Person keeper "Iven" at shrine {
    Role "keeper of names". Ancestry human. Calling cleric. Trait vitalist. Level 3. Profession priest. Peaceable.
    Offers healing "clean linen and a keeper's prayer" for 2 coin.
    Wants burial_register.
  }
  Event register_home near keeper when keepsKind(keeper, burial_register) "{keeper} takes the waxed register in both hands and turns its pages as if they might come apart. 'Every family number,' he says. 'You have brought them home.' He lays it on the bare shelf of the keepers' altar.".
  Topic custody_given with keeper "Ask {keeper} what the register means for the dead below" when keepsKind(keeper, burial_register) and not knows(actor, custody_writ) once {
    Says "'While the keepers hold the register, the named dead are in our custody, and no one can call them by name,' says {keeper}. He writes, seals the page and gives it to you. 'A custody writ. It lets you go among them below, supervised. Show it to what guards them.'".
    On discuss { Assert knows(keeper, register_survives). Retract assumesFalse(keeper, register_survives). Assert knows(actor, custody_writ). }
  }
  Initially Assert assumesFalse(keeper, register_survives).

  Topic mandate with keeper "Ask {keeper} about the keepers' dead" when not knows(keeper, register_survives) {
    Says "'We are the Keepers of Names,' says {keeper}. 'We do not command the dead or what guards them; we hold them in custody. Our register was lost in the flood, and without it the dead are only bones to anyone with a pry bar. If the register survives, bring me word of it and I will write you a custody writ. Our guardians honour the writ. Killing them also opens the way, but then there is no keeper below at all.'".
  }
  Topic writ with keeper "Tell {keeper} the register survives, and ask for custody" when knows(actor, register_survives) and not knows(actor, custody_writ) {
    Says "{keeper} listens, then sits down hard. 'I was wrong to think it lost.' He writes slowly, seals the page and gives it to you. 'This is a custody writ. It permits supervised access, not ownership of anything buried. Show it below.'".
    On discuss { Assert knows(keeper, register_survives). Retract assumesFalse(keeper, register_survives). Assert knows(actor, custody_writ). }
  }
  Topic custody_held with keeper "Speak with {keeper}" when knows(actor, custody_writ) and not refusesService(keeper, actor) {
    Says "'You carry the keepers' writ,' says {keeper}. 'Carry it honestly.'".
  }

  Observe keepers_shrine at shrine when not knows(keeper, register_survives) and not keepsKind(keeper, burial_register) "One altar is the Keeper of Names'. Its shelf, where the register should lie, is bare; {keeper} has been rewriting the name slips from memory.".
  Observe keepers_restored at shrine when knows(keeper, register_survives) and not keepsKind(keeper, burial_register) "The keepers' altar has fresh slips pinned to it, copied from an account of the surviving register.".
  Observe keepers_held at shrine when keepsKind(keeper, burial_register) "The waxed register lies open on the keepers' altar, weighted at the corners with river stones.".
  Goal false.
}

data/kits/raider-hold/hobs/folk.kyr:
Module hob_folk "Hobs" {
  Description "Hobs: small, quick, spiteful people who live by robbing the roads at night and the farms when they are hungry. They laugh while they rob, ransom what they cannot eat, and cannot abide the sound of a bell.".
  Entity party: group "Your company".
  Place outside "The approach" is room.
  Place road "The road they watch" is room.
  Place town "The settlement they rob" is room.
  Place yard "Inside the gate" is room.
  Place hall "The hall" is room.
  Place den "The chief's place" is room.
  Place pens "The pens" is room.
  Place store "The store" is room.
  Place lookout "The lookout" is room.
  Place bolt "Where the back way comes out" is room.
  Place chapel "Where they stole the bell" is room.
  Entity gate: passage "The way in".
  Entity chest: thing "The chief's chest".
  Entity heap: thing "The plunder".
  Entity backway_known: fact "The back way out of the hold".

  Person watchers "the hobs on the gate" at yard {
    Role "two hobs keeping the way in". Ancestry goblin. Calling thief. Level 1. Numbers 2.
    Called "Snig", "Tatterlip".
    Guards gate.
    State watching blocking "Two hobs squat just inside the way in, dicing with knucklebones and watching who comes.".
    State roving "The hobs who kept the gate have gone out raiding themselves; the way in is unwatched.".
  }
  Person raiders "the raiding party" at hall {
    Role "hobs who go out on the roads at night". Ancestry goblin. Calling thief. Level 1. Numbers 3.
    Called "Nettle", "Gristle", "Old Burdock".
    Uses go, assail. Plans 6 steps.
    State idle "Three hobs sharpen cudgels by the fire and argue about whose turn it is to carry the sack.".
  }
  Person gaffer "the Gaffer" at den {
    Role "chief of the hobs". Ancestry goblin. Calling thief. Level 3.
    Wants grave_rings. Wants chapel_plate. Wants jade_idol. Wants toll_silver. Wants bronze_bearing.
    State presiding "The Gaffer sits on a heap of stolen fleeces in a bishop's mitre and somebody's spectacles, and watches you with very bright eyes.".
  }
  Initially Assert serves(watchers, gaffer). Initially Assert serves(raiders, gaffer).
  Person captive "the shepherd's boy" at pens {
    Role "a boy taken off the farms". Ancestry human. Calling commoner. Level 1. Peaceable.
    State penned "A boy sits among the stolen sheep with his hands tied, trying not to cry.".
    State loose "The shepherd's boy rubs his wrists and looks at the way out.".
    Change untie "Untie the shepherd's boy" from penned to loose.
    Uses go. Plans 12 steps.
  }
  Pursuit stay_close for captive "keeping close to you" priority 30 when following(captive, party) seeks together(captive, party).
  Item handbell "a chapel handbell, wrapped in sacking" is bell in heap.
  Item chalice "a stolen chalice" is chapel_plate in chest.
  Item rings "a string of rings off the dead" is grave_rings in heap.

  Observe empty_frame at chapel when not freed(captive) "The bell is gone from its frame over the well. 'Hobs,' people say, and spit, and nobody has gone after it.".
  Observe clappers at outside when true "Up on the hold, things hang where anyone coming can see them: among them bells, every one with its clapper torn out.".
  // What the boy knows: the back way out, and what the hobs are afraid of.
  Entity bell_dread: fact "Hobs cannot abide the sound of a bell: ring one where they are and they run.".
  Initially Assert established(bell_dread).
  Topic boy_bells with captive "Ask the shepherd's boy about the hobs" when true once {
    Says "'They stole the bell off our chapel,' the boy whispers, 'and then they wouldn't touch it. Burdock wrapped it in a sack with his eyes shut. They can't stand bells. Our priest used to ring them off the farms, before.'".
    On discuss { Assert knows(actor, bell_dread). }
  }
  Topic boy_way with captive "Ask the shepherd's boy how the hobs come and go" when true once {
    Says "'There's a back way,' he says. 'I've seen them go out of it with sacks and come in without. I don't know where it comes out.'".
  }
  Rule boy_follows when state(captive, loose) and not acceptsEscort(captive, party)
    says "The boy grabs your sleeve. 'Take me home?'" { Assert acceptsEscort(captive, party). }
  Rule boy_home when at(captive, town) and following(captive, party) and not freed(captive)
    says "The boy's mother sees him from a doorway and comes running with her apron over her mouth." {
    Retract following(captive, party). Assert freed(captive). Increase quantity(party, gold) by 8.
  }
  Relation freed(group).

  // At night on the road: the raiding party waits beside it and falls on whoever passes.
  Relation quiet(group). Relation roused(entity). Relation paid(group). Relation rung(place).
  Measure shame(group). Measure losses(place).
  Rule waylay when at(party, road) and dark() and dice(clock) <= 4 and at(raiders, hall) and able(raiders)
    and not quiet(raiders) and not tolerates(raiders, party)
    says "Shapes rise out of the dark beside the road: hobs, grinning, with cudgels and a sack for whatever you are carrying." {
    Assert at(raiders, road). Assert assails(raiders, party).
  }
  Rule waylay_watch when at(party, road) and dark() and dice(clock) <= 4 and state(watchers, roving) and able(watchers)
    and at(watchers, yard) and not tolerates(watchers, party)
    says "Two hobs drop out of a tree onto the road in front of you, and two more behind." {
    Assert at(watchers, road). Assert assails(watchers, party).
  }
  Rule raiders_home when able(raiders) and at(raiders, road) and not together(raiders, party) { Assert at(raiders, hall). }
  Rule watchers_home when able(watchers) and at(watchers, road) and not together(watchers, party) { Assert at(watchers, yard). }
  // The farms: on a dark night the raiders go out to the settlement and take what they can carry.
  Rule raid when untilLight(clock) == 4 and dice(clock) <= 25 and able(raiders) and at(raiders, hall) and not quiet(raiders)
    and not at(party, town) { Increase losses(town) by 1. }
  Rule spite when roused(gaffer) and untilLight(clock) == 4 and able(raiders) and not quiet(raiders) and not at(party, town) {
    Increase losses(town) by 1.
  }
  Observe raided at town when losses(town) >= 1 and losses(town) <= 2 "Hobs were at the farms again in the night: a ewe gone, a hen-house kicked in, and little muddy footprints on a windowsill.".
  Observe raided_hard at town when losses(town) >= 3 "The farms round about have been robbed night after night. People are sleeping in their byres with pitchforks, and talking about leaving.".
  // A raiding party that was beaten stays home three nights; if it is gone, the gate-hobs take to the road instead.
  Rule lie_low when routed(raiders) and able(raiders) and not quiet(raiders) {
    Assert quiet(raiders). Set shame(raiders) to 3. Assert at(raiders, hall).
  }
  Rule lick_wounds when quiet(raiders) and not paid(gaffer) and untilLight(clock) == 1 and shame(raiders) >= 1 {
    Decrease shame(raiders) by 1.
  }
  Rule recovered when quiet(raiders) and not paid(gaffer) and shame(raiders) <= 0 {
    Retract quiet(raiders). Retract routed(raiders).
  }
  Rule new_raiders when not able(raiders) and able(watchers) and state(watchers, watching) and untilLight(clock) == 1
    and not paid(gaffer) { Assert state(watchers, roving). }
  // Trouble at the hold rouses it: the raiding party comes for whoever is inside.
  Rule alarm when (routed(watchers) or not able(watchers) or not able(gaffer)) and not roused(gaffer) { Assert roused(gaffer). }
  Pursuit defend for raiders "turning out to defend the hold" priority 30 when roused(gaffer) and not quiet(raiders)
    and (at(party, yard) or at(party, hall) or at(party, den) or at(party, pens) or at(party, lookout))
    seeks assails(raiders, party).
  Rule gaffer_fights when together(gaffer, party) and able(gaffer) and roused(gaffer) and not tolerates(gaffer, party)
    says "The Gaffer comes off his fleeces with a knife in each hand, cackling." { Assert assails(gaffer, party). }

  // A bell rung where hobs are, or within earshot of them, sends them running out of the back way.
  Action ring_bell(actor: group, site: place) "Ring the bell" {
    Description "Swing it hard. Whatever is within earshot will hear it.".
    Requires able(actor) and at(actor, site) and holding(actor, bell) and not rung(site).
    On success { Assert rung(site). }
    Result "The bell's voice goes out over everything.".
  }
  Rule bell_watchers when rung(?p) and able(watchers) and not routed(watchers) and (at(watchers, ?p) or (connects(?w, ?p, ?q) and at(watchers, ?q)))
    says "The hobs clap their hands over their ears and run, howling, the way hobs run from a bell." {
    Assert routed(watchers). Retract state(watchers, watching). Assert at(watchers, bolt).
  }
  Rule bell_raiders when rung(?p) and able(raiders) and not routed(raiders) and (at(raiders, ?p) or (connects(?w, ?p, ?q) and at(raiders, ?q)))
    says "Somewhere close a hob shrieks, and feet go scrabbling away." { Assert routed(raiders). Assert at(raiders, bolt). }
  Rule bell_gaffer when rung(?p) and able(gaffer) and (at(gaffer, ?p) or (connects(?w, ?p, ?q) and at(gaffer, ?q)))
    and not routed(gaffer) says "The Gaffer screams like a kettle and goes out of the back way with his mitre over his ears." {
    Assert routed(gaffer). Assert at(gaffer, bolt).
  }
  Rule bell_fades when rung(?p) { Retract rung(?p). }

  // A parley at the way in; and treasure for the Gaffer buys the farms a month's peace.
  Action parley(actor: group, site: place) "Call to the hobs for a parley" {
    Description "Stand where they can see you, empty-handed, and ask to talk to whoever is in charge.".
    Requires able(actor) and at(actor, site) and connects(gate, site, ?in) and at(watchers, ?in) and able(watchers)
      and state(watchers, watching) and not roused(gaffer) and not tolerates(watchers, actor).
    Time 3.
    On success { Assert tolerates(watchers, actor). Assert tolerates(raiders, actor). Assert tolerates(gaffer, actor). }
    Result "There is a lot of giggling. Then Snig sticks his head out. 'Gaffer says come in and wipe your feet. Don't touch nothing.'".
  }
  Rule caught_thieving when tolerates(gaffer, party) and not roused(gaffer) and (at(party, store) or at(party, pens))
    and ((capable(party, stealth) and dice(clock) <= 15) or (not capable(party, stealth) and dice(clock) <= 50))
    says "'OI!' A hob in the doorway points at you with his whole arm. 'THIEVES!'" { Assert roused(gaffer). }
  Rule truce_broken when roused(gaffer) and tolerates(watchers, party) {
    Retract tolerates(watchers, party). Retract tolerates(raiders, party). Retract tolerates(gaffer, party).
  }
  Topic gaffer_terms with gaffer "Ask the Gaffer what it would take to leave the farms alone" when tolerates(gaffer, party) once {
    Says "The Gaffer takes off his spectacles and polishes them on his beard. 'Shiny things,' he says. 'A ring, a cup, a pretty. Give the Gaffer something he likes and the farms can sleep. For a month, say. A month is a long time for a hob.'".
  }
  Rule tribute when keeps(gaffer, ?gift) and not paid(gaffer)
    says "The Gaffer bites it, holds it to the light and bites it again. 'The farms can sleep,' he says. 'A month.'" {
    Assert paid(gaffer). Assert quiet(raiders). Set shame(raiders) to 30.
  }
  Rule peace_wears when paid(gaffer) and untilLight(clock) == 1 and shame(raiders) >= 1 { Decrease shame(raiders) by 1. }
  Rule peace_ends when paid(gaffer) and shame(raiders) <= 0 { Retract paid(gaffer). }
  Goal not able(gaffer) or routed(gaffer) or paid(gaffer) or freed(captive).
}

data/kits/raider-hold/kit.json:
{
  "version": 1,
  "id": "raider_hold",
  "name": "A raiders' hold",
  "about": "A band that lives by raiding: a hold in wild country off the road, a road they lie in wait on, and a settlement they rob. Where it stands, which road and which settlement are bound to the region; who they are and the shape of their hold are Deem's to propose, and each changes what the company can do about them.",
  "slots": {
    "approach": {
      "is": "waypoint(?approach)",
      "requires": [
        "free(?approach)",
        "not landmark(?approach)",
        "not chokepoint(?approach)",
        "not onRoad(?approach)"
      ],
      "prefers": [
        {
          "when": "square(?town, ?near) and hours(?approach, ?near) <= 3",
          "weight": 1
        },
        {
          "when": "siteKind(?approach, cave) or siteKind(?approach, ruin) or siteKind(?approach, barrow)",
          "weight": 1
        }
      ]
    },
    "road": {
      "is": "waypoint(?road) and onRoad(?road)",
      "requires": [
        "free(?road)",
        "hours(?road, ?approach) >= 1",
        "hours(?road, ?approach) <= 6"
      ],
      "prefers": [
        {
          "when": "landmark(?road)",
          "weight": 2
        },
        {
          "when": "hours(?road, ?approach) <= 3",
          "weight": 1
        }
      ]
    },
    "prey": {
      "is": "square(?town, ?prey)",
      "requires": [
        "hours(?prey, ?approach) <= 8"
      ],
      "prefers": [
        {
          "when": "hours(?prey, ?approach) <= 4",
          "weight": 2
        },
        {
          "when": "hours(?prey, ?road) <= 3",
          "weight": 1
        }
      ]
    }
  },
  "proposals": {
    "hold": {
      "table": "raider_hold_shape",
      "by": "terrain"
    },
    "folk": {
      "table": "raider_hold_folk",
      "by": "terrain"
    }
  },
  "provides": [
    "power(@band)",
    "folk(@band, #folk)",
    "holds(@band, ?approach)",
    "ambushes(@band, ?road)",
    "raids(@band, ?prey)"
  ],
  "claims": [
    "approach"
  ],
  "tables": "tables.json",
  "modules": [
    {
      "id": "hold",
      "when": {
        "hold": "ringfort"
      },
      "bundle": "ringfort/module.json",
      "imports": {
        "party": "@party",
        "land": "@region",
        "outside": "?approach"
      }
    },
    {
      "id": "hold",
      "when": {
        "hold": "cave"
      },
      "bundle": "cave/module.json",
      "imports": {
        "party": "@party",
        "land": "@region",
        "outside": "?approach"
      }
    },
    {
      "id": "folk",
      "when": {
        "folk": "hobs"
      },
      "bundle": "hobs/module.json",
      "imports": {
        "party": "@party",
        "outside": "?approach",
        "road": "?road",
        "gate": "hold.gate",
        "yard": "hold.yard",
        "hall": "hold.hall",
        "den": "hold.den",
        "pens": "hold.pens",
        "store": "hold.store",
        "lookout": "hold.lookout",
        "bolt": "hold.bolt",
        "chest": "hold.chest",
        "heap": "hold.heap",
        "backway_known": "hold.backway_known",
        "town": "?prey",
        "chapel": "?chapel"
      }
    },
    {
      "id": "folk",
      "when": {
        "folk": "outlaws"
      },
      "bundle": "outlaws/module.json",
      "imports": {
        "party": "@party",
        "outside": "?approach",
        "road": "?road",
        "gate": "hold.gate",
        "yard": "hold.yard",
        "hall": "hold.hall",
        "den": "hold.den",
        "pens": "hold.pens",
        "store": "hold.store",
        "lookout": "hold.lookout",
        "bolt": "hold.bolt",
        "chest": "hold.chest",
        "heap": "hold.heap",
        "backway_known": "hold.backway_known",
        "town": "?prey"
      }
    }
  ]
}

data/kits/raider-hold/outlaws/folk.kyr:
Module outlaw_folk "Outlaws" {
  Description "Outlaws under Sir Hamo Ashdown, a knight who lost his lands and his name in somebody else's war. They hold up travellers on the road by day for road-money, take a tithe from the market when they please, keep a mercer for ransom, and will not refuse a challenge to single combat.".
  Entity party: group "Your company".
  Place outside "The approach" is room.
  Place road "The road they watch" is room.
  Place town "The settlement they tithe" is room.
  Place yard "Inside the gate" is room.
  Place hall "The hall" is room.
  Place den "The chief's place" is room.
  Place pens "The pens" is room.
  Place store "The store" is room.
  Place lookout "The lookout" is room.
  Place bolt "Where the back way comes out" is room.
  Entity gate: passage "The way in".
  Entity chest: thing "The chief's chest".
  Entity heap: thing "The plunder".
  Entity backway_known: fact "The back way out of the hold".

  Person sentry "the outlaws' sentry" at lookout {
    Role "a lookout with a horn". Ancestry human. Calling ranger. Level 1.
    State watching "A lean outlaw sits up where he can see the road, with a horn on a cord round his neck.".
  }
  Person band "Sir Hamo's men" at hall {
    Role "outlaws who rob the road for Sir Hamo". Ancestry human. Calling warrior. Level 1. Numbers 4.
    Called "Long Peter", "Ada Marl", "the Weasel", "Simkin".
    Guards gate.
    State keeping blocking "Sir Hamo's men lounge about with their bows strung, and one of them always has an eye on the way in.".
  }
  Person hamo "Sir Hamo Ashdown" at den {
    Role "a knight without lands, who leads the outlaws". Ancestry human. Calling warrior. Level 3.
    State brooding "Sir Hamo sits on a saddle by the fire, mending a bridle he has no horse for. His surcoat was blue once, with something on it that has been cut away.".
  }
  Initially Assert serves(sentry, hamo). Initially Assert serves(band, hamo).
  Person mercer "Odo the mercer" at pens {
    Role "a wool mercer held for ransom". Ancestry human. Calling commoner. Level 1. Peaceable.
    State held "A fat man in a good coat gone shabby sits in the pens with a chain on his leg, writing a letter to his wife about the ransom for the ninth time.".
    State loose "Odo the mercer is loose, and talking about what he will do to Sir Hamo when he has his lawyers.".
    Change unchain "Strike off the mercer's chain" from held to loose needing brawn or lockwork.
    Uses go. Plans 12 steps.
  }
  Pursuit stay_close for mercer "keeping close to you" priority 30 when following(mercer, party) seeks together(mercer, party).
  Item purse "a fat purse of road-money" is toll_silver in chest.
  Item seal "a signet ring with the arms cut off it" is grave_rings in chest.

  Relation quiet(group). Relation roused(entity). Relation demanding(group). Relation impatient(group).
  Relation dueling(group). Relation ended(group). Relation tithed(place).
  Place gone "away over the hills" is room.
  // By day on the road: the band steps out and demands road-money; whoever runs is shot at, whoever waits is robbed.
  Hazard arrows "A volley of arrows" means "Deal (1d6) physical damage to ally unless dexterity save against (12).".
  // Rules fire in order each watch: patience runs out a watch after it is tried, never in the watch of the hold-up.
  Rule loses_patience when demanding(band) and together(band, party) and impatient(band)
    says "'Have it your way,' says Long Peter, and draws." {
    Retract demanding(band). Retract impatient(band). Assert assails(band, party).
  }
  Rule growing_impatient when demanding(band) and together(band, party) and not impatient(band) { Assert impatient(band). }
  Rule hold_up when at(party, road) and not dark() and dice(clock) <= 6 and at(band, hall) and able(band)
    and not quiet(band) and not tolerates(band, party) and not ended(band)
    says "Men step out of the trees on both sides of the road with bows drawn. 'Stand,' says one. 'Road-money, in Sir Hamo's name: five crowns, or we take it off your bodies.'" {
    Assert at(band, road). Assert halts(band, party). Assert demanding(band).
  }
  Rule shot_running when demanding(band) and not together(band, party) and able(band)
    says "Arrows hiss past you as you go. Behind you someone laughs." {
    Retract demanding(band). Retract impatient(band). Assert strikes(arrows, party). Assert at(band, hall).
  }
  Action pay_road_money(actor: group, site: place) "Pay Sir Hamo's road-money, five coin" {
    Requires able(actor) and at(actor, site) and at(band, site) and demanding(band) and quantity(actor, gold) >= 5.
    On success { Decrease quantity(actor, gold) by 5. Retract demanding(band). Retract impatient(band). Assert tolerates(band, actor).
      Assert paidUp(actor). }
    Result "Long Peter weighs the coins in his palm, bows like a courtier, and the men melt back into the trees.".
  }
  Action show_empty_purse(actor: group, site: place) "Turn out your empty purse" {
    Requires able(actor) and at(actor, site) and at(band, site) and demanding(band) and quantity(actor, gold) <= 4.
    On success { Retract demanding(band). Retract impatient(band). Assert tolerates(band, actor). Assert paidUp(actor). }
    Result "They look at the purse, and at you, and Ada Marl laughs so hard she has to sit down. 'Go on,' says Long Peter. 'Sir Hamo doesn't rob the poor. Much.'".
  }
  Rule band_home when able(band) and at(band, road) and not together(band, party) and not demanding(band) { Assert at(band, hall). }
  Relation paidUp(group).
  Rule toll_paid_once when paidUp(party) and not at(party, road) { Retract paidUp(party). Retract tolerates(band, party). }
  // The market: when they are short, they ride in at noon and take a tithe.
  Measure tithes(place).
  Rule tithe when untilLight(clock) == 40 and dice(clock) <= 20 and able(band) and at(band, hall) and not quiet(band)
    and not ended(band) { Increase tithes(town) by 1. }
  Observe tithed_once at town when tithes(town) >= 1 "Sir Hamo's men rode into the market at noon and took a tithe of everything on the stalls, with the reeve standing by because there was nothing he could do.".
  // The sentry's horn rouses the hold when anyone comes up uninvited; the band comes to the way in.
  Rule horn when (at(party, outside) or at(party, bolt)) and able(sentry) and not tolerates(band, party) and not roused(hamo)
    and dice(clock) <= 50 says "A horn sounds above you, two long notes." { Assert roused(hamo). }
  Rule caught_prying when tolerates(band, party) and not roused(hamo) and (at(party, store) or at(party, pens) or at(party, den))
    and not dueling(hamo) and ((capable(party, stealth) and dice(clock) <= 15) or (not capable(party, stealth) and dice(clock) <= 50))
    says "'Hoy! Hands where I can see them!' Bows come up all round you." { Assert roused(hamo). Retract tolerates(band, party). }
  Rule band_turn_out when roused(hamo) and together(band, party) and not tolerates(band, party) and able(band)
    says "Sir Hamo's men come at you with swords out." { Assert assails(band, party). }
  Action hail(actor: group, site: place) "Hail the outlaws and ask for Sir Hamo" {
    Description "Stand where they can see you with your hands empty. Outlaws who were once a knight's men still know how a parley goes.".
    Requires able(actor) and at(actor, site) and connects(gate, site, ?in) and at(band, ?in) and able(band)
      and not roused(hamo) and not tolerates(band, actor) and not ended(band).
    Time 3.
    On success { Assert tolerates(band, actor). Assert tolerates(sentry, actor). Assert tolerates(hamo, actor). }
    Result "A long wait, and then Long Peter waves you up. 'Sir Hamo will see you. Keep your hands where we can see them.'".
  }
  // A challenge to single combat: Sir Hamo will not refuse one, and his men will not interfere.
  Action challenge(actor: group, site: place) "Challenge Sir Hamo to single combat" {
    Description "Call it out where his men can hear. A knight who refuses a challenge is no knight, and he knows it.".
    Requires able(actor) and at(actor, site) and able(hamo) and not dueling(hamo) and not ended(band)
      and (at(hamo, site) or (connects(gate, site, ?in) and at(band, ?in))).
    On success { Assert dueling(hamo). Assert tolerates(band, actor). Assert at(hamo, site). Assert assails(hamo, actor). }
    Result "Sir Hamo comes out with his sword and a dented shield. 'Very well,' he says. His men make a ring.".
  }
  Rule hamo_falls when dueling(hamo) and (not able(hamo) or routed(hamo)) and not ended(band)
    says "Sir Hamo is down. His men look at each other, and at you, and one by one they unstring their bows and go off over the hills." {
    Assert ended(band). Assert at(band, gone). Assert at(sentry, gone). Retract dueling(hamo).
  }
  Rule hamo_wins when dueling(hamo) and able(hamo) and not together(hamo, party) {
    Retract dueling(hamo). Retract tolerates(band, party). Assert at(hamo, den).
  }
  Topic hamo_tale with hamo "Ask Sir Hamo how a knight came to rob the road" when tolerates(band, party) once {
    Says "'The same way anyone does,' says Sir Hamo. 'I backed the wrong lord in a war that was none of my making, and the right one took my lands and gave them to his steward. I could starve with my name, or eat without it.' He goes back to mending the bridle. 'Beat me fairly and my men will go. They're tired of this too.'".
  }
  Topic odo_ransom with mercer "Ask the mercer about the outlaws" when true once {
    Says "'Forty crowns, they want,' says Odo. 'My wife will pay it, the dear woman, if they don't cut my ears off first. Sir Hamo won't let them. He's soft, for a cutthroat. There's a way out the back they use when the reeve's men come; I heard them laughing about it.'".
  }
  Rule odo_follows when state(mercer, loose) and not acceptsEscort(mercer, party)
    says "'Get me to a road,' says Odo, 'and there's money in it.'" { Assert acceptsEscort(mercer, party). }
  Rule odo_home when at(mercer, town) and following(mercer, party) and not ended(mercer)
    says "Odo counts out ten crowns into your hand from a purse he had sewn into his coat all along." {
    Retract following(mercer, party). Assert ended(mercer). Increase quantity(party, gold) by 10.
  }
  Goal ended(band) or ended(mercer).
}

