   "source": {
    "file": "settings/fantasy/tables/barks.json",
    "tables": [
     "npcBarks"
    ]
   },
   "definition": {
    "onEngage": [
     "{referenceName} intones: \"You shall join my immortal legion!\"",
     "{forename} declares: \"Your flesh will nourish my dark arts!\"",
     "{referenceName} cackles."
    ],
    "onSummon": [
     "{forename} commands: \"Rise, my minions!\"",
     "{referenceName} chants: \"From the depths, I call you forth!\"",
     "{forename} waves their hands about, summoning undead servants!"
    ],
    "onCrit": [
     "{referenceName} hisses: \"Feel the chill of death!\"",
     "{forename} snarls: \"Your life force is mine!\"",
     "{referenceName} growls: \"You cannot escape death!\""
    ],
    "onKill": [
     "{referenceName} intones: \"Another soul for my collection.\"",
     "{forename} murmurs: \"Your death serves a greater purpose.\"",
     "{referenceName} whispers darkly: \"So your life ends, but have no fear. Death is but a doorway.\"",
     "{forename} says coldly: \"Your soul will fuel my power.\""
    ],
    "onHitReceived": [
     "{referenceName} growls: \"You will pay for that!\"",
     "{forename} snarls: \"This isn't over yet!\""
    ],
    "onMissReceived": [
     "{forename} hisses: \"I will not be thwarted so easily!\"",
     "{referenceName} snarls: \"Not so easy, is it?\""
    ],
    "onFall": [
     "{referenceName} gasps: \"No... this cannot be...\"",
     "{forename} collapses: \"My plans... foiled...\""
    ]
   },
